DECLARE
V_COUNT INTEGER;
BEGIN
SELECT COUNT(TABLE_NAME) INTO V_COUNT from USER_TABLES where TABLE_NAME = '__EFMigrationsHistory';
IF V_COUNT = 0 THEN
Begin
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"__EFMigrationsHistory" (
    "MigrationId" NVARCHAR2(150) NOT NULL,
    "ProductVersion" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
)';
END;

End;

END IF;
EXCEPTION
WHEN OTHERS THEN
    IF(SQLCODE != -942)THEN
        RAISE;
    END IF;
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"CLINICA" (
    "ID_CLINICA" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOME" VARCHAR2(100) NOT NULL,
    "TELEFONE" VARCHAR2(20),
    CONSTRAINT "PK_CLINICA" PRIMARY KEY ("ID_CLINICA")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TUTOR" (
    "ID_TUTOR" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOME" VARCHAR2(100) NOT NULL,
    "EMAIL" VARCHAR2(150) NOT NULL,
    "SENHA_HASH" VARCHAR2(100) NOT NULL,
    "TELEFONE" VARCHAR2(20),
    "DATA_CADASTRO" DATE NOT NULL,
    CONSTRAINT "PK_TUTOR" PRIMARY KEY ("ID_TUTOR")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"DOUTOR" (
    "ID_DOUTOR" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_CLINICA" NUMBER(10) NOT NULL,
    "NOME" VARCHAR2(100) NOT NULL,
    "CRMV" VARCHAR2(20) NOT NULL,
    "EMAIL" VARCHAR2(150) NOT NULL,
    "SENHA_HASH" VARCHAR2(100) NOT NULL,
    CONSTRAINT "PK_DOUTOR" PRIMARY KEY ("ID_DOUTOR"),
    CONSTRAINT "FK_DOUTOR_CLINICA_ID_CLINICA" FOREIGN KEY ("ID_CLINICA") REFERENCES "CLINICA" ("ID_CLINICA")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"PET" (
    "ID_PET" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_TUTOR" NUMBER(10) NOT NULL,
    "NOME" VARCHAR2(100) NOT NULL,
    "ESPECIE" VARCHAR2(50) NOT NULL,
    "RACA" VARCHAR2(100),
    "DATA_NASCIMENTO" DATE,
    "PESO_KG" DECIMAL(5,2),
    CONSTRAINT "PK_PET" PRIMARY KEY ("ID_PET"),
    CONSTRAINT "FK_PET_TUTOR_ID_TUTOR" FOREIGN KEY ("ID_TUTOR") REFERENCES "TUTOR" ("ID_TUTOR")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"DISPOSITIVO_IOT" (
    "ID_DISPOSITIVO" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_PET" NUMBER(10) NOT NULL,
    "TIPO_DISPOSITIVO" VARCHAR2(50) NOT NULL,
    "DATA_INSTALACAO" DATE NOT NULL,
    CONSTRAINT "PK_DISPOSITIVO_IOT" PRIMARY KEY ("ID_DISPOSITIVO"),
    CONSTRAINT "FK_DISPOSITIVO_IOT_PET_ID_PET" FOREIGN KEY ("ID_PET") REFERENCES "PET" ("ID_PET")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"EVENTO_CLINICO" (
    "ID_EVENTO" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_PET" NUMBER(10) NOT NULL,
    "ID_DOUTOR" NUMBER(10) NOT NULL,
    "TIPO_EVENTO" VARCHAR2(30) NOT NULL,
    "DESCRICAO" VARCHAR2(500),
    "DATA_EVENTO" DATE NOT NULL,
    "STATUS" VARCHAR2(20) NOT NULL,
    CONSTRAINT "PK_EVENTO_CLINICO" PRIMARY KEY ("ID_EVENTO"),
    CONSTRAINT "CK_EVENTO_STATUS" CHECK (STATUS IN ('PENDENTE','CONCLUIDO','ATRASADO')),
    CONSTRAINT "CK_EVENTO_TIPO" CHECK (TIPO_EVENTO IN ('VACINA','CHECKUP','POS_OPERATORIO','MEDICACAO','EXAME')),
    CONSTRAINT "FK_EVENTO_CLINICO_DOUTOR_ID_DOUTOR" FOREIGN KEY ("ID_DOUTOR") REFERENCES "DOUTOR" ("ID_DOUTOR"),
    CONSTRAINT "FK_EVENTO_CLINICO_PET_ID_PET" FOREIGN KEY ("ID_PET") REFERENCES "PET" ("ID_PET")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"LEITURA_SENSOR" (
    "ID_LEITURA" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ID_DISPOSITIVO" NUMBER(10) NOT NULL,
    "TIPO_MEDIDA" VARCHAR2(50) NOT NULL,
    "VALOR_MEDIDO" DECIMAL(10,2) NOT NULL,
    "DATA_HORA_LEITURA" TIMESTAMP NOT NULL,
    CONSTRAINT "PK_LEITURA_SENSOR" PRIMARY KEY ("ID_LEITURA"),
    CONSTRAINT "FK_LEITURA_SENSOR_DISPOSITIVO_IOT_ID_DISPOSITIVO" FOREIGN KEY ("ID_DISPOSITIVO") REFERENCES "DISPOSITIVO_IOT" ("ID_DISPOSITIVO")
)';
END;
/

CREATE INDEX "IX_DISPOSITIVO_IOT_ID_PET" ON "DISPOSITIVO_IOT" ("ID_PET")
/

CREATE UNIQUE INDEX "IX_DOUTOR_CRMV" ON "DOUTOR" ("CRMV")
/

CREATE UNIQUE INDEX "IX_DOUTOR_EMAIL" ON "DOUTOR" ("EMAIL")
/

CREATE INDEX "IX_DOUTOR_ID_CLINICA" ON "DOUTOR" ("ID_CLINICA")
/

CREATE INDEX "IX_EVENTO_CLINICO_ID_DOUTOR" ON "EVENTO_CLINICO" ("ID_DOUTOR")
/

CREATE INDEX "IX_EVENTO_CLINICO_ID_PET" ON "EVENTO_CLINICO" ("ID_PET")
/

CREATE INDEX "IX_LEITURA_SENSOR_ID_DISPOSITIVO" ON "LEITURA_SENSOR" ("ID_DISPOSITIVO")
/

CREATE INDEX "IX_PET_ID_TUTOR" ON "PET" ("ID_TUTOR")
/

CREATE UNIQUE INDEX "IX_TUTOR_EMAIL" ON "TUTOR" ("EMAIL")
/

